CREATE TABLE IF NOT EXISTS scholarship_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, school_id INTEGER NOT NULL REFERENCES schools(id) ON DELETE CASCADE, rule_name TEXT NOT NULL, rule_type TEXT NOT NULL CHECK(rule_type IN ('attendance_threshold')), threshold_value REAL NOT NULL, window_days INTEGER NOT NULL, award_type TEXT NOT NULL CHECK(award_type IN ('fee_discount_percent','fee_discount_fixed')), award_value REAL NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS scholarship_awards (id INTEGER PRIMARY KEY AUTOINCREMENT, rule_id INTEGER NOT NULL REFERENCES scholarship_rules(id) ON DELETE CASCADE, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, fee_id INTEGER REFERENCES fees(id) ON DELETE SET NULL, award_type TEXT NOT NULL, award_value REAL NOT NULL, discount_applied REAL NOT NULL DEFAULT 0, attendance_pct REAL NOT NULL, evaluated_from TEXT NOT NULL, evaluated_to TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'applied' CHECK(status IN ('applied','skipped','failed')), skip_reason TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_scholarship_rules_school ON scholarship_rules(school_id); CREATE INDEX IF NOT EXISTS idx_scholarship_awards_student ON scholarship_awards(student_id); CREATE INDEX IF NOT EXISTS idx_scholarship_awards_rule ON scholarship_awards(rule_id); CREATE INDEX IF NOT EXISTS idx_scholarship_awards_fee ON scholarship_awards(fee_id);
